USE [QuanLyBanVeTau];
GO
-- 1. SỬA CẤU TRÚC CÁC BẢNG CƠ BẢN
IF NOT EXISTS (SELECT * FROM sys.columns WHERE object_id = OBJECT_ID(N'[dbo].[Tau]') AND name = N'trangThai') ALTER TABLE [dbo].[Tau] ADD [trangThai] [nvarchar](50) NULL;
IF NOT EXISTS (SELECT * FROM sys.columns WHERE object_id = OBJECT_ID(N'[dbo].[Tau]') AND name = N'soToa') ALTER TABLE [dbo].[Tau] ADD [soToa] [int] DEFAULT 0, [tongSoGhe] [int] DEFAULT 0;
IF NOT EXISTS (SELECT * FROM sys.columns WHERE object_id = OBJECT_ID(N'[dbo].[KhachHang]') AND name = N'namSinh') ALTER TABLE [dbo].[KhachHang] ADD [namSinh] [date] NULL, [laSinhVien] [bit] DEFAULT 0;
IF NOT EXISTS (SELECT * FROM sys.columns WHERE object_id = OBJECT_ID(N'[dbo].[ChuyenTau]') AND name = N'maChuyenTau') IF EXISTS (SELECT * FROM sys.columns WHERE object_id = OBJECT_ID(N'[dbo].[ChuyenTau]') AND name = N'maChuyen') EXEC sp_rename 'dbo.ChuyenTau.maChuyen', 'maChuyenTau', 'COLUMN';
IF NOT EXISTS (SELECT * FROM sys.columns WHERE object_id = OBJECT_ID(N'[dbo].[ChuyenTau]') AND name = N'trangThai') ALTER TABLE [dbo].[ChuyenTau] ADD [trangThai] [nvarchar](50) NULL;
IF NOT EXISTS (SELECT * FROM sys.columns WHERE object_id = OBJECT_ID(N'[dbo].[KhuyenMai]') AND name = N'tiLeGiamGia') ALTER TABLE [dbo].[KhuyenMai] ADD [tiLeGiamGia] [float] DEFAULT 0, [thoiGianBatDau] [datetime] NULL, [thoiGianKetThuc] [datetime] NULL;
GO

-- 2. KHỞI TẠO LẠI BẢNG HOADON VÀ VE ĐỂ ĐỒNG BỘ 100%
IF OBJECT_ID('DonDoiTraVe', 'U') IS NOT NULL DROP TABLE DonDoiTraVe;
IF OBJECT_ID('Ve', 'U') IS NOT NULL DROP TABLE Ve;
IF OBJECT_ID('HoaDon', 'U') IS NOT NULL DROP TABLE HoaDon;

CREATE TABLE [dbo].[HoaDon](
	[maHoaDon] [varchar](20) NOT NULL PRIMARY KEY,
	[ngayLapHoaDon] [datetime] NOT NULL,
	[maNV] [varchar](20) NULL,
	[maKH] [varchar](20) NULL
);
CREATE TABLE [dbo].[Ve](
	[maVe] [varchar](20) NOT NULL PRIMARY KEY,
	[maChuyenTau] [varchar](20) NULL,
	[maGhe] [varchar](20) NULL,
	[maHoaDon] [varchar](20) NULL,
	[giaVe] [float] NULL,
	[loaiVe] [nvarchar](50) NULL,
	[trangThai] [nvarchar](50) NULL
);
GO

DELETE FROM TaiKhoan; DELETE FROM NhanVien; DELETE FROM KhuyenMai; DELETE FROM ChuyenTau;
DELETE FROM Ghe; DELETE FROM ToaTau; DELETE FROM Tau; DELETE FROM KhachHang; DELETE FROM Ga;
GO

